# install.sh — make install with DESTDIR puts exactly one file in place, and
# that program works once the sources it was built from are gone.
#
# Usage: install.sh MAKE WORKDIR

MAKE=$1
WORK=$(cd "$2" && pwd -P)
TOP=$(pwd -P)
CHECKS=0
FAILURES=0

check() {
	DESC=$1
	shift
	CHECKS=$((CHECKS + 1))
	if ! "$@"
	then
		FAILURES=$((FAILURES + 1))
		echo "install: $DESC"
	fi
}

# A copy of the sources only: no build products, no t/.
mkdir -p "$WORK/src" "$WORK/dest"
cp -R "$TOP/Makefile" "$TOP/src" "$TOP/lang" "$TOP/help" "$TOP/tools" \
    "$WORK/src/"
(cd "$WORK/src" && $MAKE > "$WORK/build.log" 2>&1 &&
    $MAKE install DESTDIR="$WORK/dest" > "$WORK/install.log" 2>&1)
check "build and install succeed" [ $? -eq 0 ]
rm -rf "$WORK/src"

FILES=$(cd "$WORK/dest" && find . ! -type d | LC_ALL=C sort)
check "exactly one file installed, got: $FILES" [ "$FILES" = ./usr/local/bin/csm ]
check "installed program is executable" [ -x "$WORK/dest/usr/local/bin/csm" ]

CSM=$WORK/dest/usr/local/bin/csm
OUT=$(cd "$WORK" && LC_ALL=pl_PL.UTF-8 "$CSM" -h 2>&1)
check "built-in Polish help works" [ "${OUT#csm — zarządza}" != "$OUT" ]
OUT=$(cd "$WORK" && LC_ALL=C "$CSM" -V 2>&1)
check "version works" [ "${OUT#csm }" != "$OUT" ]

echo "install: $CHECKS checks, $FAILURES failed"
[ "$FAILURES" -eq 0 ]
